package ec.edu.ucuenca.mda.vuelos.service;
import ec.edu.ucuenca.mda.vuelos.domain.*;
import ec.edu.ucuenca.mda.vuelos.dto.*;
import ec.edu.ucuenca.mda.vuelos.repository.*;
import ec.edu.ucuenca.mda.vuelos.support.*;
import java.time.*;
import java.util.*;
import org.springframework.data.domain.Sort;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
@Service
@Transactional(readOnly=true)
public class RutaService {
    private final RutaRepository repository;
    private final AeropuertoRepository aeropuertoRepository;
    public RutaService(RutaRepository repository, AeropuertoRepository aeropuertoRepository) {
        this.repository = repository;
        this.aeropuertoRepository = aeropuertoRepository;
    }
    private RutaResponse response(Ruta value) {
        return RutaResponse.from(value);
    }
    public RutaResponse get(Long id) { return response(repository.findById(id).orElseThrow(() -> BusinessException.notFound("Ruta no encontrado"))); }
    public List<RutaResponse> list() { return repository.findAll(Sort.by("id")).stream().map(this::response).toList(); }
    @Transactional
    public RutaResponse create(RutaRequest request) {
        Aeropuerto origen = aeropuertoRepository.findById(request.origenId()).orElseThrow(() -> BusinessException.notFound("Aeropuerto no encontrado"));
        Aeropuerto destino = aeropuertoRepository.findById(request.destinoId()).orElseThrow(() -> BusinessException.notFound("Aeropuerto no encontrado"));
        BusinessException.check(!origen.getId().equals(destino.getId()), "RN-01", "Origen y destino deben ser diferentes");
        Ruta value = new Ruta();
        value.setOrigen(origen);
        value.setDestino(destino);
        return response(repository.saveAndFlush(value));
    }
}
